SELECT 'batch_007_255c609f_wav_10' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-05511bcc-4d5','sm-upload-43d08570-b2e','sm-upload-553e0240-555','sm-upload-620c477b-70a','sm-upload-660bdf12-2ce','sm-upload-70333488-8b5','sm-upload-8e189cf4-bc2','sm-upload-c659b405-246','sm-upload-f1efcbe8-2fb','sm-upload-f4c839d7-939') AND album_id='al-3e2385da217b494f06495b58255c609f') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-05511bcc-4d5','sm-upload-43d08570-b2e','sm-upload-553e0240-555','sm-upload-620c477b-70a','sm-upload-660bdf12-2ce','sm-upload-70333488-8b5','sm-upload-8e189cf4-bc2','sm-upload-c659b405-246','sm-upload-f1efcbe8-2fb','sm-upload-f4c839d7-939') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-3e2385da217b494f06495b58255c609f' AND name='逆进化ЯEVOLUTION') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-3e2385da217b494f06495b58255c609f') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-3e2385da217b494f06495b58255c609f') AS calculated_size;
